mapper.update:
update notification_record_channel
set status = 'SUCCESS', claim_token = null, error_message = null, wecom_msg_id = #{msgId},
    last_attempt_time = #{now}, update_time = #{now}
where channel_id = #{channelId} and status = 'SENDING' and claim_token = #{claimToken}

update notification_record_channel
set status = 'FAILED', claim_token = null, error_message = #{errorMessage},
    last_attempt_time = #{now}, update_time = #{now}
where channel_id = #{channelId} and status = 'SENDING' and claim_token = #{claimToken}

update notification_record_channel
set status = 'PENDING', claim_token = null, error_message = null, update_time = #{now}
where record_id = #{recordId} and status = 'FAILED'
